// 가계부 + 게시판 릴스 적용 스크립트 (프론트엔드)
// 사용법: 이 파일을 D:\\newyou_app_fe 폴더(package.json 있는 곳)에 넣고
//         터미널에서  node apply-moneybook.js
// 바뀌는 파일은 먼저 ../newyou_app_fe_money_backup_날짜 폴더에 백업해요.
const fs = require('fs');
const path = require('path');

const FILES = {
    "components/Money/moneyStore.ts": "import { useEffect, useSyncExternalStore } from 'react';\nimport api from '@/components/utils/api';\nimport { useAuth } from '@/components/contexts/AuthProvider';\n\n/**\n * 가계부 저장소\n * - 서버(/api/money)에 계정별로 저장해요.\n * - 가계부 화면과 기록 추가 화면이 같은 목록을 함께 써요.\n * - 로그아웃하면 목록을 비워요.\n */\n\nexport type MoneyType = 'INCOME' | 'EXPENSE';\n\nexport interface MoneyRecord {\n    id: string;\n    type: MoneyType;\n    amount: number;\n    category: string;\n    memo: string;\n    date: string; // YYYY-MM-DD\n}\n\nexport type MoneyInput = Omit<MoneyRecord, 'id'>;\n\n// 분류 (이모지 + 이름 + 색)\nexport const EXPENSE_CATEGORIES = [\n    { name: '식비', emoji: '🍚', color: '#F2994A' },\n    { name: '카페·간식', emoji: '☕', color: '#B7713F' },\n    { name: '교통', emoji: '🚌', color: '#3B82F6' },\n    { name: '쇼핑', emoji: '🛍️', color: '#EC4899' },\n    { name: '생활', emoji: '🏠', color: '#14B8A6' },\n    { name: '문화·취미', emoji: '🎬', color: '#8B5CF6' },\n    { name: '의료', emoji: '💊', color: '#EF4444' },\n    { name: '교육', emoji: '📚', color: '#6366F1' },\n    { name: '선물', emoji: '🎁', color: '#F06292' },\n    { name: '기타', emoji: '💸', color: '#9CA3AF' },\n];\n\nexport const INCOME_CATEGORIES = [\n    { name: '월급', emoji: '💼', color: '#4E7D32' },\n    { name: '알바', emoji: '🧑‍🍳', color: '#7BA84E' },\n    { name: '용돈', emoji: '💝', color: '#F2B705' },\n    { name: '보너스', emoji: '🎉', color: '#14B8A6' },\n    { name: '기타', emoji: '💰', color: '#9CA3AF' },\n];\n\nexport const findCategory = (type: MoneyType, name: string) =>\n    (type === 'INCOME' ? INCOME_CATEGORIES : EXPENSE_CATEGORIES).find((c) => c.name === name) ?? {\n        name,\n        emoji: type === 'INCOME' ? '💰' : '💸',\n        color: '#9CA3AF',\n    };\n\n// 12345 → \"12,345\"\nexport const formatWon = (n: number) => Math.round(n).toString().replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',');\n\n// ---------------- 내부 저장소 ----------------\nlet records: MoneyRecord[] = [];\nlet loading = false;\nconst listeners = new Set<() => void>();\nconst emit = () => listeners.forEach((l) => l());\nconst setRecords = (next: MoneyRecord[]) => {\n    records = next;\n    emit();\n};\n\nconst normalize = (raw: any): MoneyRecord => ({\n    id: String(raw.id),\n    type: raw.type === 'INCOME' ? 'INCOME' : 'EXPENSE',\n    amount: Number(raw.amount ?? 0),\n    category: raw.category ?? '기타',\n    memo: raw.memo ?? '',\n    date: raw.date ?? '',\n});\n\nconst sortRecords = (list: MoneyRecord[]) =>\n    [...list].sort((a, b) => (a.date === b.date ? Number(b.id) - Number(a.id) : b.date.localeCompare(a.date)));\n\n// ---------------- 서버와 주고받기 ----------------\nexport async function loadMoney() {\n    if (loading) return;\n    loading = true;\n    try {\n        const res = await api.get('/money');\n        setRecords(sortRecords((res.data as any[]).map(normalize)));\n    } catch (e) {\n        console.warn('가계부를 불러오지 못했어요:', e);\n    } finally {\n        loading = false;\n    }\n}\n\nexport async function addMoney(input: MoneyInput) {\n    const res = await api.post('/money', input);\n    const saved = normalize(res.data);\n    setRecords(sortRecords([...records, saved]));\n    return saved;\n}\n\nexport async function updateMoney(id: string, input: Partial<MoneyInput>) {\n    const res = await api.patch(`/money/${id}`, input);\n    const saved = normalize(res.data);\n    setRecords(sortRecords(records.map((r) => (r.id === id ? saved : r))));\n    return saved;\n}\n\nexport async function deleteMoney(id: string) {\n    await api.delete(`/money/${id}`);\n    setRecords(records.filter((r) => r.id !== id));\n}\n\n// ---------------- 화면에서 쓰는 훅 ----------------\nconst subscribe = (l: () => void) => {\n    listeners.add(l);\n    return () => listeners.delete(l);\n};\n\nexport function useMoney() {\n    const { isAuthenticated } = useAuth();\n    const list = useSyncExternalStore(subscribe, () => records, () => records);\n\n    useEffect(() => {\n        if (isAuthenticated) loadMoney();\n        else setRecords([]);\n    }, [isAuthenticated]);\n\n    return { records: list, loadMoney, addMoney, updateMoney, deleteMoney };\n}\n",
    "components/Money/MoneyBook.tsx": "import React, { useCallback, useMemo, useState } from 'react';\nimport { View, Text, StyleSheet, ScrollView, TouchableOpacity } from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { LinearGradient } from 'expo-linear-gradient';\nimport { router, useFocusEffect } from 'expo-router';\nimport AppHeader from '@/components/AppHeader';\nimport { THEME } from '@/constants/theme';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport { useRequireLogin } from '@/components/RequireLogin';\nimport { useMoney, findCategory, formatWon, MoneyRecord, MoneyType } from '@/components/Money/moneyStore';\n\n/**\n * 가계부 메인 화면\n * - 이번 달 수입 / 지출 / 남은 돈\n * - 지출 분류별 그래프\n * - 날짜별 기록 목록\n */\n\nconst INCOME_COLOR = '#2F8F5B';\nconst EXPENSE_COLOR = '#E05A5A';\nconst DAY_NAMES = ['일', '월', '화', '수', '목', '금', '토'];\n\nconst ymOf = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;\nconst todayKey = () => {\n    const d = new Date();\n    return `${ymOf(d)}-${String(d.getDate()).padStart(2, '0')}`;\n};\n\n// \"2026-10-10\" → \"10월 10일 (토)\" / 오늘·어제\nconst dateTitle = (date: string) => {\n    const [y, m, d] = date.split('-').map(Number);\n    const obj = new Date(y, m - 1, d);\n    const t = new Date();\n    const y1 = new Date();\n    y1.setDate(t.getDate() - 1);\n    const same = (a: Date, b: Date) => a.toDateString() === b.toDateString();\n    const base = `${m}월 ${d}일 (${DAY_NAMES[obj.getDay()]})`;\n    if (same(obj, t)) return `오늘 · ${base}`;\n    if (same(obj, y1)) return `어제 · ${base}`;\n    return base;\n};\n\nexport default function MoneyBook() {\n    const { records, loadMoney } = useMoney();\n    const { isAuthenticated } = useAuth();\n    const requireLogin = useRequireLogin();\n    const [month, setMonth] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1));\n    const [filter, setFilter] = useState<'ALL' | MoneyType>('ALL');\n\n    // 화면에 돌아올 때마다 최신 기록으로\n    useFocusEffect(\n        useCallback(() => {\n            if (isAuthenticated) loadMoney();\n            // eslint-disable-next-line react-hooks/exhaustive-deps\n        }, [isAuthenticated])\n    );\n\n    const ym = ymOf(month);\n    const monthRecords = useMemo(() => records.filter((r) => r.date.startsWith(ym)), [records, ym]);\n\n    const income = monthRecords.filter((r) => r.type === 'INCOME').reduce((s, r) => s + r.amount, 0);\n    const expense = monthRecords.filter((r) => r.type === 'EXPENSE').reduce((s, r) => s + r.amount, 0);\n    const balance = income - expense;\n\n    // 지출 분류별 합계 (큰 순서)\n    const byCategory = useMemo(() => {\n        const map: Record<string, number> = {};\n        monthRecords.filter((r) => r.type === 'EXPENSE').forEach((r) => {\n            map[r.category] = (map[r.category] || 0) + r.amount;\n        });\n        return Object.entries(map)\n            .map(([name, total]) => ({ ...findCategory('EXPENSE', name), total }))\n            .sort((a, b) => b.total - a.total);\n    }, [monthRecords]);\n\n    // 날짜별로 묶기\n    const groups = useMemo(() => {\n        const list = monthRecords.filter((r) => filter === 'ALL' || r.type === filter);\n        const map: Record<string, MoneyRecord[]> = {};\n        list.forEach((r) => {\n            (map[r.date] = map[r.date] || []).push(r);\n        });\n        return Object.keys(map)\n            .sort((a, b) => b.localeCompare(a))\n            .map((date) => ({ date, items: map[date] }));\n    }, [monthRecords, filter]);\n\n    const isThisMonth = ym === ymOf(new Date());\n    const changeMonth = (diff: number) => setMonth(new Date(month.getFullYear(), month.getMonth() + diff, 1));\n\n    const openAdd = (type: MoneyType) => {\n        if (!requireLogin('가계부 기록')) return;\n        router.push({ pathname: '/AddMoney', params: { type } });\n    };\n\n    return (\n        <View style={styles.container}>\n            <AppHeader title=\"가계부\" showBell={false} />\n\n            <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>\n                {/* 달 이동 */}\n                <View style={styles.monthRow}>\n                    <TouchableOpacity onPress={() => changeMonth(-1)} style={styles.monthArrow} accessibilityLabel=\"지난달\">\n                        <Ionicons name=\"chevron-back\" size={20} color={THEME.text} />\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => setMonth(new Date(new Date().getFullYear(), new Date().getMonth(), 1))}>\n                        <Text style={styles.monthText}>\n                            {month.getFullYear()}년 {month.getMonth() + 1}월\n                        </Text>\n                        {!isThisMonth && <Text style={styles.monthHint}>눌러서 이번 달로</Text>}\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => changeMonth(1)} style={styles.monthArrow} accessibilityLabel=\"다음 달\">\n                        <Ionicons name=\"chevron-forward\" size={20} color={THEME.text} />\n                    </TouchableOpacity>\n                </View>\n\n                {/* 요약 카드 */}\n                <LinearGradient colors={THEME.headerGradient} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.summary}>\n                    <Text style={styles.summaryLabel}>이번 달 남은 돈</Text>\n                    <Text style={[styles.balance, { color: balance < 0 ? EXPENSE_COLOR : THEME.text }]}>\n                        {balance < 0 ? '-' : ''}\n                        {formatWon(Math.abs(balance))}원\n                    </Text>\n                    <View style={styles.summaryRow}>\n                        <View style={styles.summaryBox}>\n                            <View style={styles.summaryBoxHead}>\n                                <View style={[styles.dot, { backgroundColor: INCOME_COLOR }]} />\n                                <Text style={styles.summaryBoxLabel}>수입</Text>\n                            </View>\n                            <Text style={[styles.summaryBoxValue, { color: INCOME_COLOR }]}>+{formatWon(income)}원</Text>\n                        </View>\n                        <View style={styles.summaryBox}>\n                            <View style={styles.summaryBoxHead}>\n                                <View style={[styles.dot, { backgroundColor: EXPENSE_COLOR }]} />\n                                <Text style={styles.summaryBoxLabel}>지출</Text>\n                            </View>\n                            <Text style={[styles.summaryBoxValue, { color: EXPENSE_COLOR }]}>-{formatWon(expense)}원</Text>\n                        </View>\n                    </View>\n                </LinearGradient>\n\n                {/* 빠른 등록 버튼 */}\n                <View style={styles.quickRow}>\n                    <TouchableOpacity style={[styles.quickButton, { backgroundColor: '#E7F5EC' }]} onPress={() => openAdd('INCOME')} activeOpacity={0.85}>\n                        <Ionicons name=\"add-circle\" size={22} color={INCOME_COLOR} />\n                        <Text style={[styles.quickText, { color: INCOME_COLOR }]}>돈 받았어요</Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity style={[styles.quickButton, { backgroundColor: '#FDECEC' }]} onPress={() => openAdd('EXPENSE')} activeOpacity={0.85}>\n                        <Ionicons name=\"remove-circle\" size={22} color={EXPENSE_COLOR} />\n                        <Text style={[styles.quickText, { color: EXPENSE_COLOR }]}>돈 썼어요</Text>\n                    </TouchableOpacity>\n                </View>\n\n                {/* 지출 분류별 */}\n                {byCategory.length > 0 && (\n                    <View style={styles.card}>\n                        <Text style={styles.cardTitle}>어디에 썼을까요?</Text>\n                        {/* 전체 막대 */}\n                        <View style={styles.stackBar}>\n                            {byCategory.map((c) => (\n                                <View key={c.name} style={{ flex: c.total, backgroundColor: c.color }} />\n                            ))}\n                        </View>\n                        {byCategory.slice(0, 5).map((c) => {\n                            const pct = expense > 0 ? Math.round((c.total / expense) * 100) : 0;\n                            return (\n                                <View key={c.name} style={styles.catRow}>\n                                    <Text style={styles.catEmoji}>{c.emoji}</Text>\n                                    <Text style={styles.catName}>{c.name}</Text>\n                                    <View style={styles.catBarTrack}>\n                                        <View style={[styles.catBarFill, { width: `${pct}%`, backgroundColor: c.color }]} />\n                                    </View>\n                                    <Text style={styles.catPct}>{pct}%</Text>\n                                    <Text style={styles.catAmount}>{formatWon(c.total)}원</Text>\n                                </View>\n                            );\n                        })}\n                    </View>\n                )}\n\n                {/* 기록 목록 */}\n                <View style={styles.listHead}>\n                    <Text style={styles.listTitle}>내역</Text>\n                    <View style={styles.filterRow}>\n                        {(\n                            [\n                                { key: 'ALL', label: '전체' },\n                                { key: 'INCOME', label: '수입' },\n                                { key: 'EXPENSE', label: '지출' },\n                            ] as const\n                        ).map((f) => {\n                            const active = filter === f.key;\n                            return (\n                                <TouchableOpacity\n                                    key={f.key}\n                                    onPress={() => setFilter(f.key)}\n                                    style={[styles.filterChip, active && styles.filterChipActive]}\n                                >\n                                    <Text style={[styles.filterText, active && styles.filterTextActive]}>{f.label}</Text>\n                                </TouchableOpacity>\n                            );\n                        })}\n                    </View>\n                </View>\n\n                {groups.length === 0 ? (\n                    <View style={styles.emptyBox}>\n                        <Text style={styles.emptyEmoji}>💰</Text>\n                        <Text style={styles.emptyTitle}>아직 기록이 없어요</Text>\n                        <Text style={styles.emptyText}>\n                            {isAuthenticated\n                                ? '오늘 쓴 돈이나 받은 돈을 기록해 보세요.'\n                                : '가계부를 쓰려면 먼저 로그인해 주세요.'}\n                        </Text>\n                    </View>\n                ) : (\n                    groups.map((g) => {\n                        const dayIncome = g.items.filter((r) => r.type === 'INCOME').reduce((s, r) => s + r.amount, 0);\n                        const dayExpense = g.items.filter((r) => r.type === 'EXPENSE').reduce((s, r) => s + r.amount, 0);\n                        return (\n                            <View key={g.date} style={styles.dayGroup}>\n                                <View style={styles.dayHead}>\n                                    <Text style={[styles.dayTitle, g.date === todayKey() && { color: THEME.primaryDark }]}>\n                                        {dateTitle(g.date)}\n                                    </Text>\n                                    <Text style={styles.daySum}>\n                                        {dayIncome > 0 && <Text style={{ color: INCOME_COLOR }}>+{formatWon(dayIncome)} </Text>}\n                                        {dayExpense > 0 && <Text style={{ color: EXPENSE_COLOR }}>-{formatWon(dayExpense)}</Text>}\n                                    </Text>\n                                </View>\n                                <View style={styles.dayCard}>\n                                    {g.items.map((r, i) => {\n                                        const cat = findCategory(r.type, r.category);\n                                        const isIncome = r.type === 'INCOME';\n                                        return (\n                                            <TouchableOpacity\n                                                key={r.id}\n                                                style={[styles.item, i > 0 && styles.itemBorder]}\n                                                onPress={() => router.push({ pathname: '/AddMoney', params: { id: r.id } })}\n                                                activeOpacity={0.7}\n                                            >\n                                                <View style={[styles.itemIcon, { backgroundColor: `${cat.color}22` }]}>\n                                                    <Text style={styles.itemEmoji}>{cat.emoji}</Text>\n                                                </View>\n                                                <View style={{ flex: 1 }}>\n                                                    <Text style={styles.itemTitle} numberOfLines={1}>\n                                                        {r.memo || r.category}\n                                                    </Text>\n                                                    <Text style={styles.itemSub}>{r.category}</Text>\n                                                </View>\n                                                <Text style={[styles.itemAmount, { color: isIncome ? INCOME_COLOR : EXPENSE_COLOR }]}>\n                                                    {isIncome ? '+' : '-'}\n                                                    {formatWon(r.amount)}원\n                                                </Text>\n                                            </TouchableOpacity>\n                                        );\n                                    })}\n                                </View>\n                            </View>\n                        );\n                    })\n                )}\n            </ScrollView>\n\n            {/* 오른쪽 아래 + 버튼 (지출 기록) */}\n            <TouchableOpacity style={styles.fab} onPress={() => openAdd('EXPENSE')} activeOpacity={0.85} accessibilityLabel=\"기록 추가\">\n                <Ionicons name=\"add\" size={30} color=\"#fff\" />\n            </TouchableOpacity>\n        </View>\n    );\n}\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: THEME.background },\n    content: { padding: 16, paddingBottom: 120 },\n\n    monthRow: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', marginBottom: 12 },\n    monthArrow: {\n        width: 34,\n        height: 34,\n        borderRadius: 17,\n        backgroundColor: THEME.card,\n        borderWidth: 1,\n        borderColor: THEME.line,\n        alignItems: 'center',\n        justifyContent: 'center',\n        marginHorizontal: 18,\n    },\n    monthText: { fontSize: 18, fontWeight: '800', color: THEME.text, textAlign: 'center' },\n    monthHint: { fontSize: 11, color: THEME.subText, textAlign: 'center', marginTop: 1 },\n\n    summary: { borderRadius: 24, padding: 18, marginBottom: 12 },\n    summaryLabel: { fontSize: 13, color: THEME.subText, fontWeight: '600' },\n    balance: { fontSize: 30, fontWeight: '800', marginTop: 4, letterSpacing: -0.5 },\n    summaryRow: { flexDirection: 'row', gap: 10, marginTop: 14 },\n    summaryBox: { flex: 1, backgroundColor: 'rgba(255,255,255,0.8)', borderRadius: 16, padding: 12 },\n    summaryBoxHead: { flexDirection: 'row', alignItems: 'center' },\n    dot: { width: 8, height: 8, borderRadius: 4, marginRight: 6 },\n    summaryBoxLabel: { fontSize: 13, color: THEME.subText, fontWeight: '600' },\n    summaryBoxValue: { fontSize: 16, fontWeight: '800', marginTop: 4 },\n\n    quickRow: { flexDirection: 'row', gap: 10, marginBottom: 14 },\n    quickButton: {\n        flex: 1,\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'center',\n        borderRadius: 16,\n        paddingVertical: 13,\n    },\n    quickText: { fontSize: 15, fontWeight: '800', marginLeft: 6 },\n\n    card: {\n        backgroundColor: THEME.card,\n        borderRadius: 20,\n        padding: 16,\n        marginBottom: 14,\n        borderWidth: 1,\n        borderColor: THEME.line,\n    },\n    cardTitle: { fontSize: 16, fontWeight: '800', color: THEME.text, marginBottom: 12 },\n    stackBar: { flexDirection: 'row', height: 12, borderRadius: 6, overflow: 'hidden', marginBottom: 12 },\n    catRow: { flexDirection: 'row', alignItems: 'center', paddingVertical: 6 },\n    catEmoji: { fontSize: 16, width: 24 },\n    catName: { fontSize: 14, color: THEME.text, fontWeight: '600', width: 72 },\n    catBarTrack: { flex: 1, height: 6, borderRadius: 3, backgroundColor: '#F0F1E8', overflow: 'hidden', marginHorizontal: 8 },\n    catBarFill: { height: 6, borderRadius: 3 },\n    catPct: { fontSize: 12, color: THEME.subText, width: 34, textAlign: 'right' },\n    catAmount: { fontSize: 13, color: THEME.text, fontWeight: '700', width: 78, textAlign: 'right' },\n\n    listHead: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: 4, marginBottom: 10 },\n    listTitle: { fontSize: 17, fontWeight: '800', color: THEME.text },\n    filterRow: { flexDirection: 'row', backgroundColor: '#EEF0E4', borderRadius: 999, padding: 3 },\n    filterChip: { paddingHorizontal: 12, paddingVertical: 5, borderRadius: 999 },\n    filterChipActive: { backgroundColor: '#FFFFFF' },\n    filterText: { fontSize: 13, color: THEME.subText, fontWeight: '600' },\n    filterTextActive: { color: THEME.primaryDark, fontWeight: '800' },\n\n    emptyBox: {\n        alignItems: 'center',\n        paddingVertical: 36,\n        borderRadius: 20,\n        borderWidth: 1,\n        borderStyle: 'dashed',\n        borderColor: THEME.line,\n    },\n    emptyEmoji: { fontSize: 40, marginBottom: 8 },\n    emptyTitle: { fontSize: 16, fontWeight: '800', color: THEME.text },\n    emptyText: { fontSize: 13, color: THEME.subText, marginTop: 4 },\n\n    dayGroup: { marginBottom: 12 },\n    dayHead: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6, paddingHorizontal: 4 },\n    dayTitle: { fontSize: 13, fontWeight: '700', color: THEME.subText },\n    daySum: { fontSize: 12, fontWeight: '700' },\n    dayCard: { backgroundColor: THEME.card, borderRadius: 18, borderWidth: 1, borderColor: THEME.line, paddingHorizontal: 12 },\n    item: { flexDirection: 'row', alignItems: 'center', paddingVertical: 12 },\n    itemBorder: { borderTopWidth: 1, borderTopColor: '#F2F3EA' },\n    itemIcon: { width: 40, height: 40, borderRadius: 20, alignItems: 'center', justifyContent: 'center', marginRight: 12 },\n    itemEmoji: { fontSize: 19 },\n    itemTitle: { fontSize: 15, fontWeight: '700', color: THEME.text },\n    itemSub: { fontSize: 12, color: THEME.subText, marginTop: 2 },\n    itemAmount: { fontSize: 15, fontWeight: '800', marginLeft: 8 },\n\n    fab: {\n        position: 'absolute',\n        right: 20,\n        bottom: 36,\n        width: 58,\n        height: 58,\n        borderRadius: 29,\n        backgroundColor: THEME.primary,\n        alignItems: 'center',\n        justifyContent: 'center',\n        shadowColor: THEME.primaryDark,\n        shadowOffset: { width: 0, height: 6 },\n        shadowOpacity: 0.3,\n        shadowRadius: 10,\n        elevation: 6,\n    },\n});\n",
    "components/Money/AddMoney.tsx": "import React, { useEffect, useState } from 'react';\nimport {\n    View,\n    Text,\n    TextInput,\n    TouchableOpacity,\n    StyleSheet,\n    ScrollView,\n    Platform,\n    Alert,\n    KeyboardAvoidingView,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { router, useLocalSearchParams } from 'expo-router';\nimport DateTimePicker from '@react-native-community/datetimepicker';\nimport AppHeader from '@/components/AppHeader';\nimport { THEME } from '@/constants/theme';\nimport {\n    useMoney,\n    EXPENSE_CATEGORIES,\n    INCOME_CATEGORIES,\n    formatWon,\n    MoneyType,\n} from '@/components/Money/moneyStore';\n\n/**\n * 가계부 기록 추가 / 수정\n *   router.push({ pathname: '/AddMoney', params: { type: 'EXPENSE' } })  → 지출 추가\n *   router.push({ pathname: '/AddMoney', params: { type: 'INCOME' } })   → 수입 추가\n *   router.push({ pathname: '/AddMoney', params: { id: '3' } })          → 3번 기록 수정\n */\n\nconst INCOME_COLOR = '#2F8F5B';\nconst EXPENSE_COLOR = '#E05A5A';\nconst DAY_NAMES = ['일', '월', '화', '수', '목', '금', '토'];\n\nconst toKey = (d: Date) =>\n    `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;\nconst fromKey = (k: string) => {\n    const [y, m, d] = k.split('-').map(Number);\n    return new Date(y, m - 1, d);\n};\n\nexport default function AddMoney() {\n    const params = useLocalSearchParams<{ id?: string; type?: string }>();\n    const { records, addMoney, updateMoney, deleteMoney } = useMoney();\n\n    const editing = params.id ? records.find((r) => r.id === String(params.id)) : undefined;\n\n    const [type, setType] = useState<MoneyType>(params.type === 'INCOME' ? 'INCOME' : 'EXPENSE');\n    const [amountText, setAmountText] = useState(''); // 숫자만\n    const [category, setCategory] = useState('');\n    const [memo, setMemo] = useState('');\n    const [date, setDate] = useState(new Date());\n    const [showPicker, setShowPicker] = useState(false);\n    const [saving, setSaving] = useState(false);\n    const [filledId, setFilledId] = useState<string | null>(null);\n\n    // 수정 모드: 기존 기록 채우기 (한 번만)\n    useEffect(() => {\n        if (editing && filledId !== editing.id) {\n            setFilledId(editing.id);\n            setType(editing.type);\n            setAmountText(String(editing.amount));\n            setCategory(editing.category);\n            setMemo(editing.memo);\n            setDate(fromKey(editing.date));\n        }\n        // eslint-disable-next-line react-hooks/exhaustive-deps\n    }, [editing?.id]);\n\n    const categories = type === 'INCOME' ? INCOME_CATEGORIES : EXPENSE_CATEGORIES;\n    const color = type === 'INCOME' ? INCOME_COLOR : EXPENSE_COLOR;\n    const amount = Number(amountText || 0);\n\n    const changeType = (t: MoneyType) => {\n        setType(t);\n        setCategory(''); // 분류 목록이 달라서 다시 고르게 해요\n    };\n\n    const addQuick = (n: number) => setAmountText(String(amount + n));\n\n    const todayK = toKey(new Date());\n    const y = new Date();\n    y.setDate(y.getDate() - 1);\n    const yesterdayK = toKey(y);\n    const dateK = toKey(date);\n    const dateLabel = `${date.getMonth() + 1}월 ${date.getDate()}일 (${DAY_NAMES[date.getDay()]})`;\n\n    const handleSave = async () => {\n        if (amount <= 0) {\n            Alert.alert('알림', '금액을 입력해 주세요.');\n            return;\n        }\n        if (!category) {\n            Alert.alert('알림', '분류를 골라 주세요.');\n            return;\n        }\n        const input = { type, amount, category, memo: memo.trim(), date: dateK };\n        setSaving(true);\n        try {\n            if (editing) await updateMoney(editing.id, input);\n            else await addMoney(input);\n            router.back();\n        } catch (e: any) {\n            Alert.alert('저장 실패', e?.response?.data?.message ?? '서버에 저장하지 못했어요. 잠시 후 다시 시도해 주세요.');\n        } finally {\n            setSaving(false);\n        }\n    };\n\n    const handleDelete = () => {\n        if (!editing) return;\n        Alert.alert('기록 삭제', '이 기록을 삭제할까요?', [\n            { text: '취소', style: 'cancel' },\n            {\n                text: '삭제',\n                style: 'destructive',\n                onPress: async () => {\n                    try {\n                        await deleteMoney(editing.id);\n                        router.back();\n                    } catch {\n                        Alert.alert('삭제 실패', '서버에서 삭제하지 못했어요.');\n                    }\n                },\n            },\n        ]);\n    };\n\n    return (\n        <View style={styles.container}>\n            <AppHeader\n                title={editing ? '기록 수정' : type === 'INCOME' ? '수입 기록' : '지출 기록'}\n                showBell={false}\n                right={editing ? [{ icon: 'trash-outline', onPress: handleDelete, accessibilityLabel: '삭제' }] : []}\n            />\n\n            <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>\n                <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps=\"handled\">\n                    {/* 지출 / 수입 */}\n                    <View style={styles.typeToggle}>\n                        {(\n                            [\n                                { key: 'EXPENSE', label: '돈 썼어요', icon: 'remove-circle' },\n                                { key: 'INCOME', label: '돈 받았어요', icon: 'add-circle' },\n                            ] as const\n                        ).map((t) => {\n                            const active = type === t.key;\n                            const c = t.key === 'INCOME' ? INCOME_COLOR : EXPENSE_COLOR;\n                            return (\n                                <TouchableOpacity\n                                    key={t.key}\n                                    onPress={() => changeType(t.key)}\n                                    style={[styles.typeButton, active && { backgroundColor: '#FFFFFF' }]}\n                                    activeOpacity={0.85}\n                                >\n                                    <Ionicons name={t.icon} size={18} color={active ? c : THEME.icon} />\n                                    <Text style={[styles.typeText, active && { color: c, fontWeight: '800' }]}>{t.label}</Text>\n                                </TouchableOpacity>\n                            );\n                        })}\n                    </View>\n\n                    {/* 금액 */}\n                    <View style={styles.amountCard}>\n                        <Text style={styles.amountLabel}>{type === 'INCOME' ? '얼마 받았나요?' : '얼마 썼나요?'}</Text>\n                        <View style={styles.amountRow}>\n                            <Text style={[styles.amountSign, { color }]}>{type === 'INCOME' ? '+' : '-'}</Text>\n                            <TextInput\n                                style={[styles.amountInput, { color }]}\n                                value={amountText ? formatWon(amount) : ''}\n                                onChangeText={(t) => setAmountText(t.replace(/[^0-9]/g, '').slice(0, 10))}\n                                placeholder=\"0\"\n                                placeholderTextColor=\"#D3D5C8\"\n                                keyboardType=\"number-pad\"\n                                autoFocus={!editing}\n                            />\n                            <Text style={[styles.amountWon, { color }]}>원</Text>\n                        </View>\n                        <View style={styles.quickRow}>\n                            {[1000, 5000, 10000, 50000].map((n) => (\n                                <TouchableOpacity key={n} style={styles.quickChip} onPress={() => addQuick(n)}>\n                                    <Text style={styles.quickText}>+{n >= 10000 ? `${n / 10000}만` : `${n / 1000}천`}</Text>\n                                </TouchableOpacity>\n                            ))}\n                            {amountText !== '' && (\n                                <TouchableOpacity style={styles.quickChip} onPress={() => setAmountText('')}>\n                                    <Ionicons name=\"close\" size={14} color={THEME.subText} />\n                                </TouchableOpacity>\n                            )}\n                        </View>\n                    </View>\n\n                    {/* 분류 */}\n                    <Text style={styles.label}>분류</Text>\n                    <View style={styles.catGrid}>\n                        {categories.map((c) => {\n                            const active = category === c.name;\n                            return (\n                                <TouchableOpacity\n                                    key={c.name}\n                                    onPress={() => setCategory(c.name)}\n                                    style={[styles.catItem, active && { borderColor: c.color, backgroundColor: `${c.color}14` }]}\n                                    activeOpacity={0.8}\n                                >\n                                    <Text style={styles.catEmoji}>{c.emoji}</Text>\n                                    <Text style={[styles.catName, active && { color: THEME.text, fontWeight: '800' }]}>{c.name}</Text>\n                                </TouchableOpacity>\n                            );\n                        })}\n                    </View>\n\n                    {/* 날짜 */}\n                    <Text style={styles.label}>날짜</Text>\n                    <View style={styles.dateRow}>\n                        <TouchableOpacity\n                            style={[styles.dateChip, dateK === todayK && styles.dateChipActive]}\n                            onPress={() => setDate(new Date())}\n                        >\n                            <Text style={[styles.dateChipText, dateK === todayK && styles.dateChipTextActive]}>오늘</Text>\n                        </TouchableOpacity>\n                        <TouchableOpacity\n                            style={[styles.dateChip, dateK === yesterdayK && styles.dateChipActive]}\n                            onPress={() => setDate(fromKey(yesterdayK))}\n                        >\n                            <Text style={[styles.dateChipText, dateK === yesterdayK && styles.dateChipTextActive]}>어제</Text>\n                        </TouchableOpacity>\n                        <TouchableOpacity style={[styles.dateChip, styles.datePick]} onPress={() => setShowPicker(!showPicker)}>\n                            <Ionicons name=\"calendar-outline\" size={16} color={THEME.primary} />\n                            <Text style={styles.datePickText}>{dateLabel}</Text>\n                        </TouchableOpacity>\n                    </View>\n                    {showPicker && (\n                        <View style={Platform.OS === 'ios' ? styles.pickerBox : undefined}>\n                            <DateTimePicker\n                                value={date}\n                                mode=\"date\"\n                                display={Platform.OS === 'ios' ? 'inline' : 'default'}\n                                themeVariant=\"light\"\n                                accentColor={THEME.primary}\n                                locale=\"ko-KR\"\n                                maximumDate={new Date(new Date().getFullYear() + 1, 11, 31)}\n                                onChange={(_, d) => {\n                                    if (Platform.OS === 'android') setShowPicker(false);\n                                    if (d) setDate(d);\n                                }}\n                            />\n                        </View>\n                    )}\n\n                    {/* 메모 */}\n                    <Text style={styles.label}>메모 (선택)</Text>\n                    <TextInput\n                        style={styles.memoInput}\n                        value={memo}\n                        onChangeText={setMemo}\n                        placeholder={type === 'INCOME' ? '예) 10월 알바비' : '예) 점심 김밥, 버스비'}\n                        placeholderTextColor={THEME.placeholder}\n                        maxLength={200}\n                    />\n\n                    {/* 저장 */}\n                    <TouchableOpacity\n                        onPress={handleSave}\n                        disabled={saving}\n                        activeOpacity={0.85}\n                        style={[styles.saveButton, { backgroundColor: color }, saving && { opacity: 0.6 }]}\n                    >\n                        <Ionicons name=\"checkmark-circle\" size={20} color=\"#fff\" />\n                        <Text style={styles.saveText}>\n                            {saving ? '저장 중...' : editing ? '수정 완료' : type === 'INCOME' ? '수입 기록하기' : '지출 기록하기'}\n                        </Text>\n                    </TouchableOpacity>\n                </ScrollView>\n            </KeyboardAvoidingView>\n        </View>\n    );\n}\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: THEME.background },\n    content: { padding: 16, paddingBottom: 60 },\n\n    typeToggle: { flexDirection: 'row', backgroundColor: '#EEF0E4', borderRadius: 999, padding: 4, marginBottom: 14 },\n    typeButton: {\n        flex: 1,\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'center',\n        paddingVertical: 10,\n        borderRadius: 999,\n    },\n    typeText: { fontSize: 15, fontWeight: '600', color: THEME.subText, marginLeft: 5 },\n\n    amountCard: {\n        backgroundColor: THEME.card,\n        borderRadius: 22,\n        padding: 18,\n        borderWidth: 1,\n        borderColor: THEME.line,\n        marginBottom: 6,\n    },\n    amountLabel: { fontSize: 14, fontWeight: '700', color: THEME.subText },\n    amountRow: { flexDirection: 'row', alignItems: 'center', marginTop: 8 },\n    amountSign: { fontSize: 30, fontWeight: '800', marginRight: 4 },\n    amountInput: { flex: 1, minWidth: 0, fontSize: 34, fontWeight: '800', paddingVertical: 4 },\n    amountWon: { fontSize: 24, fontWeight: '800', marginLeft: 4 },\n    quickRow: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 10 },\n    quickChip: {\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        borderRadius: 999,\n        backgroundColor: THEME.background,\n        borderWidth: 1,\n        borderColor: THEME.line,\n        justifyContent: 'center',\n    },\n    quickText: { fontSize: 13, fontWeight: '700', color: THEME.subText },\n\n    label: { fontSize: 14, fontWeight: '800', color: THEME.text, marginTop: 18, marginBottom: 8, marginLeft: 2 },\n\n    catGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: 8 },\n    catItem: {\n        width: '18.5%',\n        aspectRatio: 1,\n        borderRadius: 16,\n        backgroundColor: THEME.card,\n        borderWidth: 1.5,\n        borderColor: THEME.line,\n        alignItems: 'center',\n        justifyContent: 'center',\n    },\n    catEmoji: { fontSize: 22 },\n    catName: { fontSize: 11, color: THEME.subText, fontWeight: '600', marginTop: 4 },\n\n    dateRow: { flexDirection: 'row', gap: 8 },\n    dateChip: {\n        paddingHorizontal: 14,\n        paddingVertical: 9,\n        borderRadius: 999,\n        backgroundColor: THEME.card,\n        borderWidth: 1,\n        borderColor: THEME.line,\n        flexDirection: 'row',\n        alignItems: 'center',\n    },\n    dateChipActive: { backgroundColor: THEME.primarySoft, borderColor: THEME.primary },\n    dateChipText: { fontSize: 14, fontWeight: '600', color: THEME.subText },\n    dateChipTextActive: { color: THEME.primaryDark, fontWeight: '800' },\n    datePick: { flex: 1, justifyContent: 'center' },\n    datePickText: { fontSize: 14, fontWeight: '700', color: THEME.text, marginLeft: 6 },\n    pickerBox: { backgroundColor: THEME.card, borderRadius: 16, marginTop: 8, overflow: 'hidden' },\n\n    memoInput: {\n        backgroundColor: THEME.card,\n        borderWidth: 1,\n        borderColor: THEME.line,\n        borderRadius: 14,\n        paddingHorizontal: 14,\n        paddingVertical: 12,\n        fontSize: 16,\n        color: THEME.text,\n    },\n\n    saveButton: {\n        marginTop: 24,\n        height: 56,\n        borderRadius: 18,\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'center',\n    },\n    saveText: { color: '#fff', fontSize: 17, fontWeight: '800', marginLeft: 6 },\n});\n",
    "app/(money)/MoneyBook.tsx": "import MoneyBook from '@/components/Money/MoneyBook';\nimport { screen } from '@/components/screen';\n\nexport default screen(MoneyBook);\n",
    "app/(money)/AddMoney.tsx": "import AddMoney from '@/components/Money/AddMoney';\nimport { screen } from '@/components/screen';\n\nexport default screen(AddMoney, { requireLogin: '가계부' });\n",
    "app/(tabs)/index.tsx": "import React, { useState, useEffect } from 'react';\nimport { StyleSheet, View, Text, ScrollView, TouchableOpacity, StatusBar, Image } from 'react-native';\nimport { HeroBackground } from '@/components/AppHeader';\nimport { Ionicons, MaterialCommunityIcons } from '@expo/vector-icons';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport { router } from 'expo-router';\nimport { usePlans } from '@/components/Plan/PlanContext';\nimport { useAlarms, Alarm } from '@/components/contexts/AlarmContext';\nimport { useFriends } from '@/components/contexts/FriendContext';\nimport { LinearGradient } from 'expo-linear-gradient';\nimport { BASE_URL } from '@/config';\nimport { THEME } from '@/constants/theme';\nimport { useHomeCards } from '@/components/HomeCards/homeCardsStore';\nimport { useSchedules } from '@/components/Schedule/scheduleStore';\n// 로고 이미지 (require로 불러오면 VS Code에서 빨간 줄이 생기지 않아요)\nconst NewYouLogo = require('@/assets/NewYou.png');\n\ninterface Friend {\n    id: string;\n    nickname: string;\n    birthdate: { day: number; month: number } | null;\n    profileColor: string[];\n    profileImage?: string | null;\n    memo?: string;\n}\n\ninterface BirthdayInfo {\n    id: string;\n    name: string;\n    date: string;\n    month: string;\n    day: string;\n    daysUntil: number;\n}\n\nexport default function HomeScreen() {\n    const { currentUser, logout } = useAuth();\n    const { plans } = usePlans();\n    const { alarms, toggleAlarm } = useAlarms();\n    const { friends } = useFriends();\n    const { isOn } = useHomeCards(); // 마이페이지 > 홈 알람 설정에서 켠 카드만 보여줘요\n    const { schedules } = useSchedules();\n\n    const activeAlarms = alarms.filter(alarm => alarm.isActive);\n    const [currentTimeAndDay, setCurrentTimeAndDay] = useState('');\n    const [currentDate, setCurrentDate] = useState('');\n\n    const getAbsoluteImageUrl = (relativePath: string | null | undefined): string | null => {\n        if (!relativePath) return null;\n        if (relativePath.startsWith('http')) return relativePath;\n\n        const cleanBaseUrl = BASE_URL.replace(/\\/+$/, '').replace(/\\/api$/, '');\n        const cleanRelativePath = relativePath.replace(/^\\/+/g, '');\n\n        return `${cleanBaseUrl}/${cleanRelativePath}`;\n    };\n\n    const calculateUpcomingBirthdays = (friends: Friend[]): BirthdayInfo[] => {\n        const today = new Date();\n        const currentYear = today.getFullYear();\n\n        const birthdayInfos: BirthdayInfo[] = friends\n            .filter(friend => friend.birthdate)\n            .map(friend => {\n                const { day, month } = friend.birthdate!;\n                let birthdayThisYear = new Date(currentYear, month - 1, day);\n\n                if (birthdayThisYear < today) {\n                    birthdayThisYear = new Date(currentYear + 1, month - 1, day);\n                }\n\n                const timeDiff = birthdayThisYear.getTime() - today.getTime();\n                const daysUntil = Math.ceil(timeDiff / (1000 * 3600 * 24));\n\n                let dateText = '';\n                if (daysUntil === 0) {\n                    dateText = '오늘';\n                } else if (daysUntil === 1) {\n                    dateText = '내일';\n                } else if (daysUntil <= 7) {\n                    dateText = `${daysUntil}일 후`;\n                } else if (daysUntil <= 30) {\n                    const weeks = Math.floor(daysUntil / 7);\n                    const remainingDays = daysUntil % 7;\n                    if (remainingDays === 0) {\n                        dateText = `${weeks}주일 후`;\n                    } else {\n                        dateText = `${weeks}주일 ${remainingDays}일 후`;\n                    }\n                } else {\n                    const months = Math.floor(daysUntil / 30);\n                    dateText = `${months}개월 후`;\n                }\n\n                const monthNames = ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'];\n\n                return {\n                    id: friend.id,\n                    name: friend.nickname,\n                    date: dateText,\n                    month: monthNames[month - 1],\n                    day: `${day}일`,\n                    daysUntil: daysUntil\n                };\n            })\n            .sort((a, b) => a.daysUntil - b.daysUntil);\n\n        return birthdayInfos.slice(0, 2);\n    };\n\n    const upcomingBirthdays = calculateUpcomingBirthdays(friends);\n\n    // 메뉴마다 아이콘 색(color)과 동그라미 배경색(bg)을 따로 정해요.\n    // lib: 'mci' 이면 MaterialCommunityIcons 아이콘을 써요 (없으면 Ionicons).\n    const menuItems = [\n        { id: '1', title: '알람', icon: 'alarm', color: '#F2994A', bg: '#FFF1E3' },\n        { id: '2', title: '생일', icon: 'cake-variant', lib: 'mci', color: '#F06292', bg: '#FFE4EC' },\n        { id: '3', title: '계획', icon: 'calendar', color: '#3FA36B', bg: '#E4F5EA' },\n        { id: '4', title: '일정', icon: 'time', color: '#3B82F6', bg: '#E6F0FF' },\n        { id: '5', title: '채팅', icon: 'chatbubbles', color: '#8B5CF6', bg: '#F1EAFF' },\n        { id: '6', title: '강의', icon: 'school', color: '#14B8A6', bg: '#DFF6F2' },\n        { id: '7', title: '메모', icon: 'document-text', color: '#D9A400', bg: '#FFF6D1' },\n        { id: '8', title: '책읽기', icon: 'book', color: '#B7713F', bg: '#F8ECE2' },\n        { id: '9', title: '선물', icon: 'gift', color: '#EF4444', bg: '#FFE7E7' },\n        { id: '10', title: '좋아요', icon: 'heart', color: '#EC4899', bg: '#FDE6F2' },\n        { id: '11', title: '게시판', icon: 'reader', color: '#6366F1', bg: '#E9EAFF' },\n        { id: '12', title: '가계부', icon: 'wallet', color: '#0EA5E9', bg: '#DFF3FC' },\n    ];\n\n    const groupedMenuItems = [];\n    for (let i = 0; i < menuItems.length; i += 4) {\n        groupedMenuItems.push(menuItems.slice(i, i + 4));\n    }\n\n    const handleProfilePress = () => {\n        router.push('/(tabs)/my');\n    };\n\n    const handleNotificationPress = () => {\n        router.push('/Notification');\n    };\n\n    const handleBirthdayPress = () => {\n        router.push('/Present');\n    };\n\n    const today = new Date();\n\n    // ⭐⭐ YYYY-MM-DD 형식으로 오늘 날짜 생성 ⭐⭐\n    const getFormattedDate = (date: Date): string => {\n        const year = date.getFullYear();\n        const month = String(date.getMonth() + 1).padStart(2, '0');\n        const day = String(date.getDate()).padStart(2, '0');\n        return `${year}-${month}-${day}`;\n    };\n\n    const todayFormattedDate = getFormattedDate(today);\n\n    // ⭐⭐ plan.planDate를 사용하여 오늘 계획 필터링 ⭐⭐\n    const todayPlans = plans.filter(plan => {\n        // plan.planDate는 YYYY-MM-DD 형식의 문자열입니다\n        return plan.planDate === todayFormattedDate;\n    });\n\n    // 오늘 계획만 표시\n    const sortedPlans = [\n        { title: '오늘', data: todayPlans }\n    ].filter(section => section.data.length > 0);\n\n    const formattedDate = `${today.getFullYear()}년 ${(today.getMonth() + 1)}월 ${today.getDate()}일`;\n\n    useEffect(() => {\n        const updateTimeAndDate = () => {\n            const now = new Date();\n\n            const hours = now.getHours();\n            const minutes = now.getMinutes();\n            const ampm = hours >= 12 ? '오후' : '오전';\n            const formattedHours = hours % 12 || 12;\n            const formattedMinutes = minutes < 10 ? `0${minutes}` : minutes;\n            const daysOfWeek = ['일요일', '월요일', '화요일', '수요일', '목요일', '금요일', '토요일'];\n            const dayOfWeek = daysOfWeek[now.getDay()];\n\n            const year = now.getFullYear();\n            const month = now.getMonth() + 1;\n            const day = now.getDate();\n            const formattedDate = `${year}년 ${month}월 ${day}일`;\n\n            setCurrentTimeAndDay(`(${ampm} ${formattedHours}:${formattedMinutes}) (${dayOfWeek})`);\n            setCurrentDate(formattedDate);\n        };\n\n        updateTimeAndDate();\n        const intervalId = setInterval(updateTimeAndDate, 60000);\n\n        return () => clearInterval(intervalId);\n    }, []);\n\n    // 오늘 요일의 시간표 일정 (시간 순서)\n    const JS_DAY_KEYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];\n    const todaySchedules = schedules\n        .filter((s) => s.day === JS_DAY_KEYS[new Date().getDay()])\n        .sort((a, b) => a.time.localeCompare(b.time));\n\n    // \"14:30\", 1.5 → \"오후 2:30 · 1시간 30분\"\n    const formatScheduleTime = (time: string, duration: number) => {\n        const [h, m] = time.split(':').map(Number);\n        const ampm = h < 12 ? '오전' : '오후';\n        const hh = h % 12 === 0 ? 12 : h % 12;\n        const dh = Math.floor(duration);\n        const dm = Math.round((duration - dh) * 60);\n        const len = dh && dm ? `${dh}시간 ${dm}분` : dh ? `${dh}시간` : `${dm}분`;\n        return `${ampm} ${hh}:${String(m || 0).padStart(2, '0')} · ${len}`;\n    };\n\n    const handleToggleAlarm = async (alarmId: string) => {\n        try {\n            await toggleAlarm(alarmId);\n        } catch (error) {\n            console.error(\"알람 토글 중 API 오류 발생:\", error);\n            alert('알람 상태 변경 중 오류가 발생했습니다.');\n        }\n    };\n\n    const renderBirthdayProfile = (friendId: string) => {\n        const friend = friends.find(f => f.id === friendId);\n        if (!friend) return null;\n\n        if (friend.profileImage) {\n            const absoluteUri = getAbsoluteImageUrl(friend.profileImage);\n\n            if (absoluteUri) {\n                return (\n                    <Image\n                        source={{ uri: absoluteUri }}\n                        style={styles.birthdayProfileImage}\n                    />\n                );\n            }\n        }\n\n        const initials = friend.nickname.charAt(0).toUpperCase();\n        return (\n            <LinearGradient\n                colors={(friend.profileColor?.length >= 2 ? friend.profileColor : ['#FFB75E', '#F06292']) as [string, string, ...string[]]}\n                style={styles.birthdayProfileIcon}\n                start={{ x: 0, y: 0 }}\n                end={{ x: 1, y: 1 }}\n            >\n                <Text style={styles.birthdayProfileText}>{initials}</Text>\n            </LinearGradient>\n        );\n    };\n\n    return (\n        <View style={styles.container}>\n            <StatusBar barStyle=\"dark-content\" />\n            {/* 로그인 화면처럼 위까지 이어지는 둥근 그라데이션 헤더 */}\n            <HeroBackground>\n                <View style={styles.header}>\n                    <View style={styles.headerLeft}>\n                        <Image source={NewYouLogo} style={styles.newYouLogoImage} resizeMode=\"contain\" />\n                    </View>\n                    <View style={styles.centerTimeContainer}>\n                        <Ionicons name=\"calendar-outline\" size={18} color=\"#666\" />\n                        <View style={styles.dateTimeWrapper}>\n                            <Text style={styles.currentDateText}>{currentDate}</Text>\n                            <Text style={styles.currentTimeText}>{currentTimeAndDay}</Text>\n                        </View>\n                        <Ionicons name=\"time-outline\" size={18} color=\"#666\" />\n                    </View>\n                    <TouchableOpacity style={styles.notificationIconContainer} onPress={handleNotificationPress}>\n                        <Ionicons name=\"notifications-outline\" size={26} color={THEME.text} />\n                    </TouchableOpacity>\n                </View>\n            </HeroBackground>\n            <View style={styles.main}>\n                <ScrollView contentContainerStyle={styles.scrollContent}>\n                    <View style={styles.functionSection}>\n                        {isOn('plan') && (\n                        <View style={styles.functionCard}>\n                            <View style={styles.functionHeader}>\n                                <View style={styles.functionHeaderLeft}>\n                                    <Ionicons name=\"calendar\" size={20} color=\"#4ECDC4\" />\n                                    <Text style={styles.functionTitle}>{formattedDate} (오늘 계획)</Text>\n                                </View>\n                                <TouchableOpacity onPress={() => router.push('/Plan')}>\n                                    <Text style={styles.seeAllText}>모두 보기</Text>\n                                </TouchableOpacity>\n                            </View>\n                            {sortedPlans.length > 0 ? (\n                                sortedPlans.map(section => (\n                                    <View key={section.title}>\n                                        <Text style={styles.planDateHeader}>{section.title}</Text>\n                                        {section.data.map(schedule => (\n                                            <View key={schedule.id} style={styles.scheduleItem}>\n                                                <View style={styles.scheduleLeft}>\n                                                    <TouchableOpacity style={[styles.checkBox, { backgroundColor: '#fff', borderColor: schedule.color || '#4ECDC4' }]}>\n                                                    </TouchableOpacity>\n                                                    <View style={styles.scheduleInfo}>\n                                                        <Text style={styles.scheduleTitle}>\n                                                            {schedule.title}\n                                                        </Text>\n                                                        <Text style={styles.scheduleDetails}>\n                                                            {schedule.content.substring(0, 20)}...\n                                                        </Text>\n                                                    </View>\n                                                </View>\n                                            </View>\n                                        ))}\n                                    </View>\n                                ))\n                            ) : (\n                                <View style={styles.emptyState}>\n                                    <Text style={styles.emptyStateText}>오늘 등록된 계획이 없습니다</Text>\n                                </View>\n                            )}\n                        </View>\n                        )}\n                        {isOn('alarm') && (\n                        <View style={styles.functionCard}>\n                            <View style={styles.functionHeader}>\n                                <View style={styles.functionHeaderLeft}>\n                                    <Ionicons name=\"alarm\" size={20} color=\"#FF6B6B\" />\n                                    <Text style={styles.functionTitle}>알람</Text>\n                                </View>\n                                <TouchableOpacity onPress={() => router.push('/AlarmList')}>\n                                    <Text style={styles.seeAllText}>모두 보기</Text>\n                                </TouchableOpacity>\n                            </View>\n                            {activeAlarms.length > 0 ? (\n                                activeAlarms.slice(0, 2).map((alarm: Alarm) => (\n                                    <View key={alarm.id} style={styles.alarmItem}>\n                                        <View style={styles.alarmLeft}>\n                                            <Text style={styles.alarmTime}>\n                                                {alarm.time}\n                                            </Text>\n                                            <Text style={styles.alarmLabel}>\n                                                {alarm.label}\n                                            </Text>\n                                        </View>\n                                        <TouchableOpacity\n                                            style={[styles.alarmToggle, { backgroundColor: alarm.isActive ? '#4ECDC4' : '#E8E8E8' }]}\n                                            onPress={() => handleToggleAlarm(alarm.id)}\n                                        >\n                                            <View style={[styles.alarmToggleCircle, { transform: [{ translateX: alarm.isActive ? 18 : 2 }] }]} />\n                                        </TouchableOpacity>\n                                    </View>\n                                ))\n                            ) : (\n                                <View style={styles.emptyState}>\n                                    <Text style={styles.emptyStateText}>설정된 알람이 없습니다</Text>\n                                </View>\n                            )}\n                        </View>\n                        )}\n                        {isOn('birthday') && (\n                        <View style={styles.functionCard}>\n                            <View style={styles.functionHeader}>\n                                <View style={styles.functionHeaderLeft}>\n                                    <Ionicons name=\"gift\" size={20} color=\"#9B59B6\" />\n                                    <Text style={styles.functionTitle}>생일 알람</Text>\n                                </View>\n                                <TouchableOpacity onPress={() => router.push('/Birthday')}>\n                                    <Text style={styles.seeAllText}>모두 보기</Text>\n                                </TouchableOpacity>\n                            </View>\n                            {upcomingBirthdays.length > 0 ? (\n                                upcomingBirthdays.map((birthday) => (\n                                    <TouchableOpacity\n                                        key={birthday.id}\n                                        style={styles.birthdayItem}\n                                        onPress={handleBirthdayPress}\n                                        activeOpacity={0.8}\n                                    >\n                                        {renderBirthdayProfile(birthday.id)}\n                                        <View style={styles.birthdayInfo}>\n                                            <Text style={styles.birthdayName}>{birthday.name}</Text>\n                                            <Text style={styles.birthdayDate}>\n                                                {birthday.month} {birthday.day} ({birthday.date})\n                                            </Text>\n                                        </View>\n                                        <View style={[styles.birthdayBadge, {\n                                            backgroundColor: birthday.daysUntil <= 7 ? '#ffebee' : '#fff2e5'\n                                        }]}>\n                                            <Text style={styles.birthdayBadgeText}>\n                                                {birthday.daysUntil === 0 ? '🎉' : birthday.daysUntil <= 7 ? '🔔' : '🎂'}\n                                            </Text>\n                                        </View>\n                                    </TouchableOpacity>\n                                ))\n                            ) : (\n                                <View style={styles.emptyState}>\n                                    <Text style={styles.emptyStateText}>등록된 생일이 없습니다</Text>\n                                </View>\n                            )}\n                        </View>\n                        )}\n                        {isOn('schedule') && (\n                        <View style={styles.functionCard}>\n                            <View style={styles.functionHeader}>\n                                <View style={styles.functionHeaderLeft}>\n                                    <Ionicons name=\"time\" size={20} color=\"#3B82F6\" />\n                                    <Text style={styles.functionTitle}>오늘 일정</Text>\n                                </View>\n                                <TouchableOpacity onPress={() => router.push('/timetable')}>\n                                    <Text style={styles.seeAllText}>모두 보기</Text>\n                                </TouchableOpacity>\n                            </View>\n                            {todaySchedules.length > 0 ? (\n                                todaySchedules.slice(0, 3).map((item) => (\n                                    <View key={item.id} style={styles.scheduleItem}>\n                                        <View style={[styles.scheduleColorBar, { backgroundColor: item.color || '#E6F0FF' }]} />\n                                        <View style={styles.scheduleInfo}>\n                                            <Text style={styles.scheduleTitle}>{item.title}</Text>\n                                            <Text style={styles.scheduleDetails}>{formatScheduleTime(item.time, item.duration)}</Text>\n                                        </View>\n                                    </View>\n                                ))\n                            ) : (\n                                <View style={styles.emptyState}>\n                                    <Text style={styles.emptyStateText}>오늘 시간표 일정이 없습니다</Text>\n                                </View>\n                            )}\n                        </View>\n                        )}\n                    </View>\n                    <View style={styles.menuSection}>\n                        <Text style={styles.sectionTitle}>메뉴</Text>\n                        {groupedMenuItems.map((group, groupIndex) => (\n                            <View key={groupIndex} style={styles.menuRow}>\n                                {group.map((item) => (\n                                    <TouchableOpacity\n                                        key={item.id}\n                                        style={styles.menuItem}\n                                        onPress={() => {\n                                            if (item.id === '1') {\n                                                router.push('/AlarmList');\n                                            } else if (item.id === '2') {\n                                                router.push('/Birthday');\n                                            } else if (item.id === '3') {\n                                                router.push('/Plan');\n                                            } else if (item.id === '4') {\n                                                router.push('/Schedule');\n                                            } else if (item.id === '5') {\n                                                router.push('/ChatMain');\n                                            } else if (item.id === '6') {\n                                                router.push('/MyClass');\n                                            } else if (item.id === '7') {\n                                                router.push('/Note');\n                                            } else if (item.id === '8') {\n                                                router.push('/Books');\n                                            } else if (item.id === '9') {\n                                                router.push('/Present');\n                                            } else if (item.id === '10') {\n                                                router.push('/Like');\n                                            } else if (item.id === '11') {\n                                                router.push('/MyBoard');\n                                            } else if (item.id === '12') {\n                                                router.push('/MoneyBook');\n                                            } else {\n                                                console.log(`${item.title} 클릭`);\n                                            }\n                                        }}\n                                    >\n                                        <View style={[styles.iconContainer, { backgroundColor: item.bg }]}>\n                                            {(item as any).lib === 'mci' ? (\n                                                <MaterialCommunityIcons name={item.icon as any} size={30} color={item.color} />\n                                            ) : (\n                                                <Ionicons name={item.icon as any} size={30} color={item.color} />\n                                            )}\n                                        </View>\n                                        <Text style={styles.menuText}>{item.title}</Text>\n                                    </TouchableOpacity>\n                                ))}\n                                {group.length < 4 &&\n                                    Array(4 - group.length)\n                                        .fill(null)\n                                        .map((_, index) => <View key={`empty-${index}`} style={styles.emptyItem} />)}\n                            </View>\n                        ))}\n                    </View>\n                </ScrollView>\n            </View>\n        </View>\n    );\n}\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: THEME.background, marginBottom: 50 },\n    header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 10, paddingVertical: 2 },\n    headerLeft: { flexDirection: 'row', alignItems: 'center' },\n    newYouLogoImage: { width: 84, height: 56 },\n    profileSection: { padding: 5, alignItems: 'center' },\n    profileContainer: { alignItems: 'center' },\n    profileImage: { width: 28, height: 28, borderRadius: 14, marginBottom: 4 },\n    profileNickname: { fontSize: 12, fontWeight: '600', color: '#333' },\n    notificationIconContainer: { padding: 5 },\n    main: { flex: 1, backgroundColor: THEME.background },\n    scrollContent: { padding: 20 },\n    functionSection: { marginBottom: 30 },\n    functionCard: { backgroundColor: '#fff', borderRadius: 16, padding: 16, marginBottom: 16, shadowColor: '#000', shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.1, shadowRadius: 8, elevation: 3 },\n    functionHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 },\n    functionHeaderLeft: { flexDirection: 'row', alignItems: 'center' },\n    functionTitle: { fontSize: 18, fontWeight: 'bold', color: '#333', marginLeft: 8 },\n    seeAllText: { fontSize: 14, color: THEME.primary, fontWeight: '600' },\n    scheduleItem: { flexDirection: 'row', alignItems: 'center', paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: '#f5f5f5' },\n    scheduleLeft: { flex: 1, flexDirection: 'row', alignItems: 'center' },\n    checkBox: { width: 20, height: 20, borderRadius: 10, borderWidth: 2, justifyContent: 'center', alignItems: 'center', marginRight: 12 },\n    scheduleInfo: { flex: 1 },\n    scheduleColorBar: { width: 6, height: 34, borderRadius: 3, marginRight: 12 },\n    scheduleTitle: { fontSize: 16, fontWeight: '600', color: '#333', marginBottom: 2 },\n    scheduleDetails: { fontSize: 14, color: '#666' },\n    alarmItem: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: '#f5f5f5' },\n    alarmLeft: { flex: 1 },\n    alarmTime: { fontSize: 20, fontWeight: 'bold', color: '#333', marginBottom: 4 },\n    alarmLabel: { fontSize: 14, color: '#666' },\n    alarmToggle: { width: 44, height: 24, borderRadius: 12, justifyContent: 'center', position: 'relative' },\n    alarmToggleCircle: { width: 20, height: 20, borderRadius: 10, backgroundColor: '#fff', position: 'absolute', shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.2, shadowRadius: 2, elevation: 2 },\n    birthdayItem: { flexDirection: 'row', alignItems: 'center', paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: '#f5f5f5' },\n    birthdayProfileImage: { width: 32, height: 32, borderRadius: 16, marginRight: 12 },\n    birthdayProfileIcon: { width: 32, height: 32, borderRadius: 16, justifyContent: 'center', alignItems: 'center', marginRight: 12 },\n    birthdayProfileText: { fontSize: 16, fontWeight: 'bold', color: '#ffffff' },\n    birthdayInfo: { flex: 1 },\n    birthdayName: { fontSize: 16, fontWeight: '600', color: '#333', marginBottom: 2 },\n    birthdayDate: { fontSize: 14, color: '#666' },\n    birthdayBadge: { width: 28, height: 28, borderRadius: 14, backgroundColor: '#fff2e5', justifyContent: 'center', alignItems: 'center' },\n    birthdayBadgeText: { fontSize: 16 },\n    emptyState: { paddingVertical: 20, alignItems: 'center' },\n    emptyStateText: { fontSize: 14, color: '#999' },\n    menuSection: { backgroundColor: '#fff', borderRadius: 16, padding: 16, shadowColor: '#000', shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.1, shadowRadius: 8, elevation: 3, marginBottom: 50 },\n    sectionTitle: { fontSize: 18, fontWeight: 'bold', color: '#333', marginBottom: 16, marginLeft: 4 },\n    menuRow: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 6 },\n    menuItem: { flex: 1, alignItems: 'center', paddingVertical: 10, marginHorizontal: 2 },\n    emptyItem: { flex: 1, marginHorizontal: 5 },\n    iconContainer: { width: 56, height: 56, borderRadius: 28, backgroundColor: '#f0edff', justifyContent: 'center', alignItems: 'center', marginBottom: 8 },\n    menuText: { fontSize: 13, color: '#333', fontWeight: '600', textAlign: 'center' },\n    planDateHeader: { fontSize: 16, fontWeight: 'bold', color: '#333', marginTop: 10, marginBottom: 8, borderBottomWidth: 1, borderBottomColor: THEME.primary, paddingBottom: 4 },\n    centerTimeContainer: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(255,255,255,0.75)', paddingHorizontal: 10, paddingVertical: 8, borderRadius: 16 },\n    dateTimeWrapper: { alignItems: 'center', marginHorizontal: 5 },\n    currentDateText: { fontSize: 14, fontWeight: 'bold', color: '#333', marginBottom: 2 },\n    currentTimeText: { fontSize: 14, fontWeight: '600', color: '#666' },\n   \n});",
    "app/(tabs)/board.tsx": "import React, { useState, useEffect } from 'react';\nimport {\n    View,\n    Text,\n    TouchableOpacity,\n    StyleSheet,\n    Dimensions,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { useLocalSearchParams, router } from 'expo-router';\nimport BoardMain from '@/components/Boards/BoardMain';\nimport OnlineClass from '@/components/OnlineClass/OnlineClass';\nimport MainReel from '@/components/Reels/MainReel';\nimport AppHeader from '@/components/AppHeader';\nimport { THEME } from '@/constants/theme';\n\nconst { width } = Dimensions.get('window');\n\ninterface TabButtonProps {\n    title: string;\n    isActive: boolean;\n    onPress: () => void;\n}\n\nconst TabButton: React.FC<TabButtonProps> = ({ title, isActive, onPress }) => (\n    <TouchableOpacity\n        style={[styles.tabButton, isActive && styles.activeTabButton]}\n        onPress={onPress}\n        activeOpacity={0.7}\n    >\n        <Text style={[styles.tabButtonText, isActive && styles.activeTabButtonText]}>\n            {title}\n        </Text>\n    </TouchableOpacity>\n);\n\nconst Board: React.FC = () => {\n    const params = useLocalSearchParams();\n    // 초기 상태를 'board'로 설정\n    const [activeTab, setActiveTab] = useState<'board' | 'onlineClass' | 'reels'>('board');\n\n    // 초기 activeTab 설정 로직 개선\n    // 컴포넌트가 마운트될 때, params에 'activeTab'이 'onlineClass'로 명시되어 있으면 설정합니다.\n    useEffect(() => {\n        // params가 존재하고, activeTab 파라미터가 'onlineClass'일 때만 상태를 변경합니다.\n        if (params.activeTab === 'onlineClass') {\n            setActiveTab('onlineClass');\n        } else if (params.activeTab === 'reels') {\n            setActiveTab('reels');\n        }\n\n        // **중요**: 의존성 배열에서 `params.activeTab`만 명시하여 해당 값 변경 시에만 실행되도록 합니다.\n        // 또는 마운트 시에만 실행하고 싶다면, 빈 배열 `[]`을 사용합니다.\n        // 여기서는 URL을 통해 들어올 때 한 번만 적용되도록 `[]`로 두어 중복 실행을 막습니다.\n    }, []);\n\n    // **팁**: `useLocalSearchParams`가 객체로 반환되므로, `params` 전체를 의존성 배열에 넣는 것은\n    // 불필요한 리렌더링을 유발할 수 있습니다.\n\n    const getHeaderTitle = () => {\n        switch (activeTab) {\n            case 'board':\n                return '게시판';\n            case 'onlineClass':\n                return '온라인 수업';\n            case 'reels':\n                return '릴스';\n            default:\n                return '게시판';\n        }\n    };\n\n    const renderContent = () => {\n        switch (activeTab) {\n            case 'board':\n                return <BoardMain />;\n            case 'onlineClass':\n                return <OnlineClass />;\n            case 'reels':\n                return <MainReel embedded />;\n            default:\n                return <BoardMain />;\n        }\n    };\n\n    const handleMyBoardPress = () => {\n        // 탭 화면에서는 navigation.navigate 대신 router.push 를 써야 해요.\n        router.push('/MyBoard');\n    };\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더 (햇살 색) */}\n            <AppHeader\n                title={getHeaderTitle()}\n                hero\n                showBack={false}\n                right={[{ icon: 'clipboard-outline', onPress: handleMyBoardPress, accessibilityLabel: '내 게시판' }]}\n            />\n\n            {/* 게시판 / 온라인 수업 전환 */}\n            <View style={styles.tabWrap}>\n                <View style={styles.tabContainer}>\n                    <TabButton\n                        title=\"게시판\"\n                        isActive={activeTab === 'board'}\n                        onPress={() => setActiveTab('board')}\n                    />\n                    <TabButton\n                        title=\"온라인 수업\"\n                        isActive={activeTab === 'onlineClass'}\n                        onPress={() => setActiveTab('onlineClass')}\n                    />\n                    <TabButton\n                        title=\"릴스\"\n                        isActive={activeTab === 'reels'}\n                        onPress={() => setActiveTab('reels')}\n                    />\n                </View>\n            </View>\n\n            <View style={styles.contentContainer}>\n                {renderContent()}\n            </View>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: {\n        flex: 1,\n        backgroundColor: THEME.background,\n    },\n    tabWrap: {\n        paddingHorizontal: 16,\n        paddingTop: 12,\n        backgroundColor: THEME.background,\n    },\n    tabContainer: {\n        flexDirection: 'row',\n        backgroundColor: '#EEF0E4',\n        borderRadius: 999,\n        padding: 4,\n    },\n    tabButton: {\n        flex: 1,\n        paddingVertical: 9,\n        alignItems: 'center',\n        justifyContent: 'center',\n        borderRadius: 999,\n    },\n    activeTabButton: {\n        backgroundColor: '#FFFFFF',\n        shadowColor: THEME.subText,\n        shadowOffset: { width: 0, height: 1 },\n        shadowOpacity: 0.15,\n        shadowRadius: 4,\n        elevation: 2,\n    },\n    tabButtonText: {\n        fontSize: 15,\n        color: THEME.subText,\n        fontWeight: '600',\n    },\n    activeTabButtonText: {\n        color: THEME.primary,\n        fontWeight: '800',\n    },\n    contentContainer: {\n        flex: 1,\n    },\n});\n\nexport default Board;\n",
    "components/Reels/MainReel.tsx": "// MainReel.js 파일\nimport React, { useState } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    TouchableOpacity,\n    StatusBar,\n    SafeAreaView,\n    Alert,\n} from 'react-native';\nimport { Ionicons as Icon } from '@expo/vector-icons';\nimport { router } from 'expo-router';\n\n// 경로 수정 (MainReel 내부에서 컴포넌트 import)\nimport Reels from './Reels';\nimport MyReels from './MyReels';\nimport AppHeader from '@/components/AppHeader';\n\n// embedded: 게시판 탭 안에 넣을 때는 위쪽 헤더를 숨겨요.\nconst MainReel = ({ embedded = false }: { embedded?: boolean }) => {\n    const [activeTab, setActiveTab] = useState('reels');\n    // ⭐️ 선택된 릴의 ID를 저장하는 상태 추가\n    const [initialReelId, setInitialReelId] = useState(null);\n\n    const handleGoBack = () => {\n        if (router.canGoBack()) {\n            router.back();\n        } else {\n            Alert.alert(\"알림\", \"더 이상 뒤로 갈 화면이 없습니다.\");\n        }\n    };\n\n    // ⭐️ MyReels에서 릴 클릭 시 호출되는 함수\n    const handleReelSelect = (reelId) => {\n        setInitialReelId(reelId); // 선택된 릴 ID 저장\n        setActiveTab('reels');     // Reels 탭으로 전환\n    };\n\n    // ⭐️ Reels 컴포넌트에 전달할 초기 릴 ID를 계산합니다.\n    // Reels 탭이 활성화될 때만 initialReelId를 전달하고,\n    // Reels 컴포넌트가 로드된 후에는 null로 재설정하여, 스크롤링 시 초기 위치로 돌아가지 않게 방지합니다.\n    const reelProps = activeTab === 'reels' ? { initialReelId } : {};\n\n\n    return (\n        <View style={styles.safeArea}>\n            {!embedded && <StatusBar barStyle=\"light-content\" backgroundColor=\"#000\" />}\n\n            {/* 공통 헤더 (어두운 화면용) - 게시판 탭 안에서는 숨겨요 */}\n            {!embedded && <AppHeader title=\"릴스\" variant=\"dark\" onBack={handleGoBack} />}\n\n            {/* 탭: Reels / My Reels */}\n            <View style={styles.headerContainer}>\n                <View style={styles.tabContainer}>\n                    <TouchableOpacity\n                        style={[styles.tab, activeTab === 'reels' && styles.activeTab]}\n                        onPress={() => {\n                            setActiveTab('reels');\n                            setInitialReelId(null); // 탭 전환 시 초기 릴 ID 초기화\n                        }}\n                    >\n                        <Text style={[styles.tabText, activeTab === 'reels' && styles.activeTabText]}>\n                            Reels\n                        </Text>\n                    </TouchableOpacity>\n\n                    <TouchableOpacity\n                        style={[styles.tab, activeTab === 'myReels' && styles.activeTab]}\n                        onPress={() => setActiveTab('myReels')}\n                    >\n                        <Text style={[styles.tabText, activeTab === 'myReels' && styles.activeTabText]}>\n                            My Reels\n                        </Text>\n                    </TouchableOpacity>\n                </View>\n            </View>\n\n            {/* Content: Reels 컴포넌트가 flex: 1 공간을 가득 채웁니다. */}\n            {/* 게시판 탭 안에서는 아래 탭 바에 가리지 않게 여백을 둬요 */}\n            <View style={[styles.contentContainer, embedded && { marginBottom: 96 }]}>\n                {activeTab === 'reels' ? (\n                    // ⭐️ Reels 컴포넌트에 initialReelId 상태를 전달\n                    <Reels {...reelProps} onScrollFinished={() => setInitialReelId(null)} />\n                ) : (\n                    // ⭐️ MyReels 컴포넌트에 릴 선택 시 호출될 콜백 함수를 전달\n                    <MyReels onReelSelect={handleReelSelect} />\n                )}\n            </View>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    safeArea: {\n        flex: 1,\n        backgroundColor: '#000',\n    },\n    headerContainer: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'space-between',\n        backgroundColor: '#000',\n        paddingHorizontal: 10,\n    },\n    backButton: {\n        padding: 5,\n        width: 40,\n    },\n    spacer: {\n        width: 40,\n    },\n    tabContainer: {\n        flexDirection: 'row',\n        flex: 1,\n        justifyContent: 'center',\n    },\n    tab: {\n        paddingHorizontal: 15,\n        paddingVertical: 12,\n        alignItems: 'center',\n    },\n    activeTab: {\n        borderBottomWidth: 2,\n        borderBottomColor: '#fff',\n    },\n    tabText: {\n        fontSize: 16,\n        color: '#888',\n        fontWeight: '600',\n    },\n    activeTabText: {\n        color: '#fff',\n    },\n    contentContainer: {\n        flex: 1, // 남은 공간 모두 차지\n    },\n});\n\nexport default MainReel;"
};

const root = process.cwd();
if (!fs.existsSync(path.join(root, 'package.json')) || !fs.existsSync(path.join(root, 'app'))) {
    console.error('❌ newyou_app_fe 폴더(package.json 있는 곳)에서 실행해 주세요.');
    process.exit(1);
}
const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
const backupDir = path.join(root, '..', 'newyou_app_fe_money_backup_' + stamp);
let changed = 0, same = 0;
for (const [rel, content] of Object.entries(FILES)) {
    const target = path.join(root, rel);
    const old = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
    if (old !== null && old.replace(/\r\n/g, '\n') === content) { same++; continue; }
    if (old !== null) {
        const b = path.join(backupDir, rel);
        fs.mkdirSync(path.dirname(b), { recursive: true });
        fs.writeFileSync(b, old, 'utf8');
    }
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content, 'utf8');
    console.log((old === null ? '🆕 새 파일  ' : '✏️  바꿈     ') + rel);
    changed++;
}
console.log(`\n✅ 완료: ${changed}개 바꿈, ${same}개는 이미 같음`);
if (changed) console.log('📦 백업 폴더: ' + backupDir);
console.log('👉 이제  npx expo start -c  로 다시 켜 주세요.');